<script>
// ===== CUSTOM SVG TIMELINE CHART =====
(function() {
  const svg = document.getElementById('main-timeline');
  const W = 2100, H = 560;
  const margin = { top: 40, right: 60, bottom: 60, left: 100 };
  const cW = W - margin.left - margin.right;
  const cH = H - margin.top - margin.bottom;

  // Data: [year, estimated annual new titles (thousands)]
  const data = [
    [500, 0.008],
    [600, 0.01],
    [700, 0.03],
    [800, 0.1],
    [900, 0.15],
    [1000, 0.25],
    [1100, 0.5],
    [1200, 1],
    [1300, 2],
    [1400, 4],
    [1440, 5],
    [1500, 50],
    [1550, 100],
    [1600, 300],
    [1650, 500],
    [1700, 1000],
    [1750, 2000],
    [1800, 5000],
    [1850, 15000],
    [1900, 50000],
    [1950, 200000],
    [2000, 500000]
  ];

  const xMin = 500, xMax = 2000;
  const yLogMin = -2.2, yLogMax = 6; // log10 range

  function xPos(year) { return margin.left + (year - xMin) / (xMax - xMin) * cW; }
  function yPos(val) {
    const logVal = Math.log10(Math.max(val, 0.001));
    return margin.top + (1 - (logVal - yLogMin) / (yLogMax - yLogMin)) * cH;
  }

  // Defs: gradients
  const defs = document.createElementNS('http://www.w3.org/2000/svg', 'defs');

  // Manuscript era gradient (brown)
  const grad1 = document.createElementNS('http://www.w3.org/2000/svg', 'linearGradient');
  grad1.id = 'areaGradMS';
  grad1.setAttribute('x1', '0'); grad1.setAttribute('y1', '0');
  grad1.setAttribute('x2', '0'); grad1.setAttribute('y2', '1');
  const s1a = document.createElementNS('http://www.w3.org/2000/svg', 'stop');
  s1a.setAttribute('offset', '0%'); s1a.setAttribute('stop-color', '#8B6F47'); s1a.setAttribute('stop-opacity', '0.6');
  const s1b = document.createElementNS('http://www.w3.org/2000/svg', 'stop');
  s1b.setAttribute('offset', '100%'); s1b.setAttribute('stop-color', '#8B6F47'); s1b.setAttribute('stop-opacity', '0.08');
  grad1.appendChild(s1a); grad1.appendChild(s1b);
  defs.appendChild(grad1);

  // Print era gradient (orange)
  const grad2 = document.createElementNS('http://www.w3.org/2000/svg', 'linearGradient');
  grad2.id = 'areaGradPrint';
  grad2.setAttribute('x1', '0'); grad2.setAttribute('y1', '0');
  grad2.setAttribute('x2', '0'); grad2.setAttribute('y2', '1');
  const s2a = document.createElementNS('http://www.w3.org/2000/svg', 'stop');
  s2a.setAttribute('offset', '0%'); s2a.setAttribute('stop-color', '#CC5500'); s2a.setAttribute('stop-opacity', '0.55');
  const s2b = document.createElementNS('http://www.w3.org/2000/svg', 'stop');
  s2b.setAttribute('offset', '100%'); s2b.setAttribute('stop-color', '#CC5500'); s2b.setAttribute('stop-opacity', '0.06');
  grad2.appendChild(s2a); grad2.appendChild(s2b);
  defs.appendChild(grad2);

  svg.appendChild(defs);

  // Grid lines
  const gridGroup = document.createElementNS('http://www.w3.org/2000/svg', 'g');
  gridGroup.setAttribute('class', 'grid');

  // Y grid (log scale)
  for (let logVal = -2; logVal <= 6; logVal++) {
    const y = yPos(Math.pow(10, logVal));
    const line = document.createElementNS('http://www.w3.org/2000/svg', 'line');
    line.setAttribute('x1', margin.left); line.setAttribute('y1', y);
    line.setAttribute('x2', W - margin.right); line.setAttribute('y2', y);
    line.setAttribute('stroke', 'rgba(139,111,71,0.12)');
    line.setAttribute('stroke-width', '1');
    if (logVal % 2 === 0) line.setAttribute('stroke-dasharray', '4,4');
    gridGroup.appendChild(line);

    // Y label
    const label = document.createElementNS('http://www.w3.org/2000/svg', 'text');
    label.setAttribute('x', margin.left - 12); label.setAttribute('y', y + 5);
    label.setAttribute('text-anchor', 'end');
    label.setAttribute('font-family', 'Source Sans 3, sans-serif');
    label.setAttribute('font-size', '13');
    label.setAttribute('fill', '#7B5B3A');
