const { chromium } = require('playwright');
const path = require('path');

(async () => {
  const browser = await chromium.launch({ headless: true });
  const context = await browser.newContext({
    viewport: { width: 2400, height: 3394 },
    deviceScaleFactor: 1.5,
  });

  const page = await context.newPage();

  // Listen for the poster-ready signal
  const readyPromise = new Promise((resolve) => {
    page.on('console', msg => {
      if (msg.text().includes('poster-ready')) resolve();
    });
    // Also listen for postMessage via page.evaluate
    page.evaluate(() => {
      return new Promise((resolve) => {
        window.addEventListener('message', (event) => {
          if (event.data && event.data.type === 'poster-ready') resolve();
        });
        // Fallback timeout
        setTimeout(resolve, 8000);
      });
    }).then(() => {});
  });

  const htmlPath = path.resolve('/app/output/poster.html');
  await page.goto(`file://${htmlPath}`, { waitUntil: 'networkidle', timeout: 30000 });

  // Wait for fonts and charts
  await page.waitForTimeout(2000);

  // Wait for charts to render
  try {
    await page.evaluate(() => {
      return new Promise((resolve) => {
        window.addEventListener('message', (event) => {
          if (event.data && event.data.type === 'poster-ready') resolve();
        });
        setTimeout(resolve, 8000);
      });
    });
  } catch (e) {
    console.log('Timeout waiting for charts, proceeding with capture');
  }

  // Extra wait for rendering
  await page.waitForTimeout(2000);

  // Take screenshot of the body element (full poster)
  await page.screenshot({
    path: '/app/output/final_poster.png',
    fullPage: false,
    clip: { x: 0, y: 0, width: 2400, height: 3394 },
  });

  console.log('Poster saved to /app/output/final_poster.png');

  await browser.close();
})();

